# Hypothesis: each 1 gets a plus of 7s; each 2 gets diagonal 4s. Verify against demo fully, then apply to test.
def f(g):
    g=[r[:] for r in g]
    for i,rw in enumerate(g):
        for j,c in enumerate(rw):
            if c==1:
                for di,dj in ((-1,0),(1,0),(0,-1),(0,1)):
                    ni,nj=i+di,j+dj
                    if 0<=ni<len(g) and 0<=nj<len(g[0]) and g[ni][nj]==0: g[ni][nj]=7
            elif c==2:
                for di,dj in ((-1,-1),(-1,1),(1,-1),(1,1)):
                    ni,nj=i+di,j+dj
                    if 0<=ni<len(g) and 0<=nj<len(g[0]) and g[ni][nj]==0: g[ni][nj]=4
    return g
